:root{
  --green-900:#122f22;--green-800:#183a2a;--green-700:#1f4a35;--green-600:#2e7d4f;--green-500:#3a9d63;
  --gold:#e0a72e;--gold-dark:#c8901f;--gold-soft:rgba(224,167,46,.14);
  --ink:#16241c;--body:#33413a;--muted:#6b7b72;--bg:#f6f8f4;--card:#fff;--line:#e3ebe3;
  --ring:rgba(46,125,79,.35);--shadow:0 10px 30px rgba(18,47,34,.10);--shadow-sm:0 2px 10px rgba(18,47,34,.06);--radius:16px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Roboto,Helvetica,Arial,sans-serif;color:var(--body);background:var(--bg);line-height:1.6;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
h1,h2,h3{color:var(--ink);line-height:1.15;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.5rem,3vw,2.1rem)}
h3{font-size:1.15rem;font-weight:750}
p{margin:0 0 1rem}
.wrap{max-width:1160px;margin:0 auto;padding:0 22px}
.section{padding:60px 0}
.narrow{max-width:820px}
.eyebrow{display:inline-block;font-size:.78rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--gold-dark);background:var(--gold-soft);padding:6px 12px;border-radius:999px;margin-bottom:16px}
.lead{font-size:1.08rem;color:var(--muted)}

.btn{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.98rem;padding:13px 22px;border-radius:12px;border:1px solid transparent;cursor:pointer;transition:transform .12s,box-shadow .12s,background .12s;white-space:nowrap}
.btn:active{transform:translateY(1px)}
.btn-gold{background:var(--gold);color:#173d1f}
.btn-gold:hover{background:var(--gold-dark)}
.btn-primary{background:var(--green-600);color:#fff;box-shadow:0 6px 16px rgba(46,125,79,.28)}
.btn-primary:hover{background:var(--green-700)}
.btn-ghost{background:#fff;color:var(--ink);border:1px solid var(--line)}
.btn-ghost:hover{border-color:var(--green-500);color:var(--green-700)}
.btn-outline{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-outline:hover{background:rgba(255,255,255,.14);border-color:#fff}
.btn-block{width:100%;justify-content:center}

header.site{position:sticky;top:0;z-index:50;background:rgba(246,248,244,.92);backdrop-filter:saturate(140%) blur(10px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;min-height:104px;gap:16px;padding:10px 0}
.brand{display:flex;align-items:center;gap:10px}
.brand .logo{height:84px;width:auto}
.brand .mark{width:64px;height:64px;border-radius:12px;background:linear-gradient(135deg,var(--green-600),var(--green-500));place-items:center;color:#fff;font-weight:900;font-size:1.2rem;display:none}
.nav-actions{display:flex;align-items:center;gap:12px}
.nav-phone{font-weight:800;color:var(--green-700);display:flex;align-items:center;gap:7px}
@media(max-width:640px){.nav-phone span.lbl{display:none}}
@media(max-width:560px){.brand .logo{height:64px}.nav{min-height:86px}}

/* page hero (info pages) */
.phero{position:relative;color:#fff;background:linear-gradient(120deg,var(--green-900),var(--green-700));overflow:hidden}
.phero::after{content:"";position:absolute;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(224,167,46,.16),transparent 62%);top:-150px;right:-100px;pointer-events:none}
.phero .wrap{position:relative;z-index:1;padding:54px 22px 58px}
.phero h1{color:#fff;font-size:clamp(2rem,4.6vw,2.9rem);margin-bottom:.15em}
.phero h1 .accent{color:var(--gold)}
.phero p{color:#d7e4da;font-size:1.12rem;max-width:62ch;margin:0}
.phero .eyebrow{color:var(--gold);background:rgba(224,167,46,.16)}

/* service hero (photo bg) */
.shero{position:relative;color:#fff;background-color:var(--green-900);background-size:cover;background-position:center;overflow:hidden}
.shero::before{content:"";position:absolute;inset:0;background:linear-gradient(115deg,rgba(11,29,18,.93),rgba(13,36,22,.68) 55%,rgba(15,42,26,.46));z-index:0}
.shero .wrap{position:relative;z-index:1;padding:56px 22px 62px}
.shero .eyebrow{color:var(--gold);background:rgba(224,167,46,.16)}
.shero h1{color:#fff;font-size:clamp(2rem,4.8vw,3rem);margin-bottom:.15em}
.shero h1 .accent{color:var(--gold)}
.shero .sub{color:#e6efe8;font-size:1.16rem;max-width:60ch;margin:0 0 20px}
.shero .hero-cta{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px}

.crumb2{font-size:.85rem;color:#bcd0c1;margin-bottom:14px}
.crumb2 a{color:#e6efe8;font-weight:600}
.crumb2 a:hover{color:var(--gold)}
.crumb2 .sep{margin:0 8px;color:#6d8a76}
.crumb2 .cur{color:#bcd0c1}

.grid2{display:grid;grid-template-columns:1.2fr .8fr;gap:36px;align-items:start}
@media(max-width:820px){.grid2{grid-template-columns:1fr;gap:26px}}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm)}
.inc{list-style:none;margin:0;padding:0}
.inc li{padding:9px 0 9px 30px;position:relative;font-size:.96rem;color:var(--body);border-bottom:1px solid var(--line)}
.inc li:last-child{border-bottom:0}
.inc li::before{content:"\2713";position:absolute;left:0;top:9px;color:var(--gold-dark);font-weight:900}

.info-list{list-style:none;margin:0;padding:0}
.info-list li{display:flex;gap:12px;padding:14px 0;border-bottom:1px solid var(--line)}
.info-list li:last-child{border-bottom:0}
.info-list .ic{width:40px;height:40px;flex:none;border-radius:10px;background:var(--gold-soft);display:grid;place-items:center;font-size:1.2rem}
.info-list .k{font-weight:800;color:var(--ink);display:block;margin-bottom:1px}
.info-list .v{color:var(--body);font-size:.95rem}
.info-list a{color:var(--green-700);font-weight:700}

.tint{background:linear-gradient(180deg,#eef3ea,var(--bg))}
.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:8px}
@media(max-width:820px){.steps{grid-template-columns:1fr}}
.step{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:24px;box-shadow:var(--shadow-sm)}
.step .n{width:40px;height:40px;border-radius:50%;background:var(--green-700);color:#fff;display:grid;place-items:center;font-weight:900;margin-bottom:14px}
.step h3{font-size:1.05rem;margin-bottom:5px}
.step p{font-size:.93rem;margin:0}

.valgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
@media(max-width:820px){.valgrid{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.valgrid{grid-template-columns:1fr}}
.val{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px;box-shadow:var(--shadow-sm)}
.val h3{font-size:1.02rem;margin-bottom:5px}
.val h3 .ck{color:var(--gold-dark);font-weight:900;margin-right:6px}
.val p{font-size:.92rem;color:var(--body);margin:0}

.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}
.chip{background:#fff;border:1px solid var(--line);border-radius:999px;padding:7px 14px;font-size:.85rem;font-weight:600;color:var(--green-800)}
a.chip:hover{border-color:var(--green-500);color:var(--green-700)}
.shero .chip{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.28);color:#eaf3ec}

.form-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:26px}
.form-card h3{font-size:1.3rem;margin-bottom:2px}
.form-card .fsub{color:var(--muted);font-size:.95rem;margin-bottom:16px}
.field{margin-bottom:13px}
.field label{display:block;font-size:.82rem;font-weight:700;color:var(--ink);margin-bottom:5px}
.field input,.field select,.field textarea{width:100%;padding:11px 13px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:.95rem;color:var(--ink);background:#fbfdfa;transition:border-color .12s,box-shadow .12s}
.field input:focus,.field select:focus,.field textarea:focus{outline:none;border-color:var(--green-500);box-shadow:0 0 0 4px var(--ring)}
.field textarea{min-height:96px;resize:vertical}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:13px}
@media(max-width:520px){.grid-2{grid-template-columns:1fr}}
.reassure{display:flex;align-items:center;gap:8px;justify-content:center;color:var(--muted);font-size:.82rem;font-weight:600;margin-top:12px}

.prose{max-width:820px}
.prose h2{font-size:1.35rem;margin:34px 0 10px}
.prose h2:first-child{margin-top:0}
.prose p{color:var(--body)}
.prose ul{margin:0 0 1rem;padding-left:20px}
.prose li{margin-bottom:8px}
.legal-meta{color:var(--muted);font-size:.9rem;margin-bottom:22px}
.legal-note{background:var(--gold-soft);border:1px solid rgba(224,167,46,.4);border-radius:12px;padding:16px 18px;font-size:.92rem;color:#5c4a1e;margin-bottom:26px}

details{background:var(--card);border:1px solid var(--line);border-radius:12px;margin-bottom:12px;box-shadow:var(--shadow-sm);overflow:hidden}
details[open]{border-color:var(--green-500)}
summary{cursor:pointer;list-style:none;padding:16px 50px 16px 20px;font-weight:750;color:var(--ink);position:relative}
summary::-webkit-details-marker{display:none}
summary::after{content:"+";position:absolute;right:20px;top:50%;transform:translateY(-50%);font-size:1.4rem;font-weight:700;color:var(--gold-dark)}
details[open] summary::after{content:"\2013"}
.faq-a{padding:0 20px 18px;color:var(--body);font-size:.95rem}

.cta-band{background:linear-gradient(120deg,var(--green-800),var(--green-600));color:#fff;text-align:center}
.cta-band .wrap{padding:52px 22px}
.cta-band h2{color:#fff}
.cta-band p{color:#dbeede;max-width:52ch;margin:0 auto 18px}
.cta-band .hero-cta{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}

footer.site{background:var(--green-900);color:#c9dccf;padding:56px 0 32px}
footer.site a:hover{color:#fff;text-decoration:underline}
footer.site h4{color:#fff;font-size:.82rem;letter-spacing:.1em;text-transform:uppercase;margin:0 0 14px}
footer.site ul{list-style:none;margin:0;padding:0}
footer.site li{margin-bottom:9px;font-size:.92rem}
.foot-brand img{height:84px;margin-bottom:14px;background:#fff;padding:8px 12px;border-radius:10px}
.foot-brand p{font-size:.9rem;color:#a9c3b1}
.foot-phone{color:#fff;font-weight:800;font-size:1.15rem;margin:8px 0 2px;display:inline-block}
.subs{font-size:.85rem;color:#9fbaa7;line-height:1.9;margin-top:6px}
.foot-bottom{border-top:1px solid rgba(255,255,255,.12);margin-top:30px;padding-top:20px;font-size:.82rem;color:#9fbaa7}

.modal-overlay{position:fixed;inset:0;background:rgba(12,26,18,.62);backdrop-filter:blur(3px);display:none;align-items:flex-start;justify-content:center;padding:5vh 18px;z-index:100;overflow-y:auto}
.modal-overlay.open{display:flex}
.modal{background:var(--card);border-radius:var(--radius);box-shadow:0 24px 60px rgba(0,0,0,.35);width:100%;max-width:520px;position:relative;padding:28px 26px 24px}
.modal h3{font-size:1.4rem;margin:0;padding-right:44px}
.modal .fsub{color:var(--muted);font-size:.95rem;margin:4px 0 16px}
.modal-close{position:absolute;top:14px;right:14px;width:38px;height:38px;border-radius:10px;border:1px solid var(--line);background:#fff;font-size:1.4rem;line-height:1;color:var(--muted);cursor:pointer;display:grid;place-items:center}
.modal-close:hover{background:#f3f6f1;color:var(--ink)}
body.no-scroll{overflow:hidden}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

/* --- nav dropdown + mobile (site nav v3: centered menu, icon buttons) --- */
.ic-svg{width:1em;height:1em;display:inline-block;vertical-align:-0.125em;flex:none}
.brand .mark{display:none!important}
.brand{flex:0 0 auto}
.nav-actions{flex:0 0 auto}
.btn-green{background:var(--green-600);color:#fff;box-shadow:0 6px 16px rgba(46,125,79,.26)}
.btn-green:hover{background:var(--green-700)}
.btn-gold{background:var(--gold);color:#173d1f}
.btn-gold:hover{background:var(--gold-dark)}
.nav-links{display:flex;gap:24px;align-items:center;flex:1 1 auto;justify-content:center}
.nav-links > a,.drop-toggle{font-weight:700;color:var(--ink);font-size:.96rem;background:none;border:0;cursor:pointer;font-family:inherit;display:inline-flex;align-items:center;gap:5px;padding:6px 0}
.nav-links > a:hover,.nav-links > a.active,.drop-toggle:hover,.has-drop.active > .drop-toggle{color:var(--green-700)}
.nav-links > a.active{border-bottom:2px solid var(--gold)}
.caret{font-size:.72rem;transition:transform .15s;display:inline-flex}
.has-drop{position:relative}
.has-drop.active > .drop-toggle{border-bottom:2px solid var(--gold)}
.dropdown{position:absolute;top:100%;left:50%;transform:translateX(-50%) translateY(8px);min-width:238px;background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);padding:8px;display:flex;flex-direction:column;opacity:0;visibility:hidden;transition:opacity .15s,transform .15s;z-index:70}
.has-drop:hover .dropdown,.has-drop:focus-within .dropdown,.has-drop.open .dropdown{opacity:1;visibility:visible;transform:translateX(-50%) translateY(5px)}
.has-drop:hover .caret,.has-drop:focus-within .caret,.has-drop.open .caret{transform:rotate(180deg)}
.dropdown a{padding:10px 12px;border-radius:9px;font-weight:600;color:var(--ink);font-size:.92rem;display:flex;align-items:center;gap:10px;border:0}
.dropdown a:hover{background:#f1f6f0;color:var(--green-700)}
.dropdown a .di{width:8px;height:8px;border-radius:50%;background:var(--gold);flex:none}
.nav-toggle{display:none;width:46px;height:46px;border-radius:10px;border:1px solid var(--line);background:#fff;cursor:pointer;place-items:center;font-size:1.35rem;color:var(--ink)}
.foot-top{display:grid;grid-template-columns:1.4fr 1fr 1fr .8fr 1.1fr;gap:26px}
@media(max-width:900px){
  .nav-links{display:none;position:absolute;top:100%;left:0;right:0;background:#fff;border-bottom:1px solid var(--line);flex-direction:column;align-items:stretch;gap:0;padding:10px 22px 16px;margin:0;box-shadow:var(--shadow)}
  header.site.nav-open .nav-links{display:flex}
  .nav-links > a,.drop-toggle{padding:12px 4px;font-size:1rem;border-bottom:1px solid var(--line);width:100%;justify-content:space-between}
  .nav-links > a.active{border-bottom:1px solid var(--line)}
  .has-drop{position:static}
  .dropdown{position:static;transform:none;opacity:1;visibility:visible;box-shadow:none;border:0;border-radius:0;padding:2px 0 8px 12px;min-width:0}
  .nav-toggle{display:grid}
}
@media(max-width:900px){.nav-actions{gap:8px}}
@media(max-width:600px){.ph-num{display:none}.nav-actions .btn{padding:12px 14px}}
@media(max-width:400px){.nav-actions .btn-gold{display:none}}
@media(max-width:860px){.foot-top{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.foot-top{grid-template-columns:1fr}}

